-- 153: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_153_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_153_guard;
INSERT INTO _migration_153_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_011' AND NOT (q.topic_id IS 'topic_was_electronics_b002_3' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the period of a 50 Hz sinusoidal waveform?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 5 ms","B. 10 ms","C. 20 ms","D. 50 ms"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Period is the reciprocal of frequency: one divided by 50 seconds equals 0.02 seconds, which is 20 milliseconds. Therefore the correct answer is C: 20 ms.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_011' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_153_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_012' AND NOT (q.topic_id IS 'topic_was_electronics_b002_3' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does inductive reactance change when frequency increases?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It decreases in inverse proportion to frequency","B. It remains fixed for a given coil","C. It becomes equal to resistance at every frequency","D. It increases in direct proportion to frequency"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Inductive reactance is two pi times frequency times inductance, so increasing frequency increases opposition for a fixed coil. Therefore the correct answer is D: It increases in direct proportion to frequency.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_012' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_153_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_013' AND NOT (q.topic_id IS 'topic_was_electronics_b002_3' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'At series resonance, how do inductive and capacitive reactances compare?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They are equal in magnitude","B. Both reactances become zero individually","C. Inductive reactance is twice capacitive reactance","D. Circuit resistance becomes infinite"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Equal opposite reactances cancel in a series RLC circuit, leaving impedance at its minimum resistive value. Therefore the correct answer is A: They are equal in magnitude.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_013' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_153_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_014' AND NOT (q.topic_id IS 'topic_was_electronics_b002_3' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 2 H inductor carries 3 A. How much energy is stored in its magnetic field?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3 J","B. 9 J","C. 6 J","D. 12 J"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Stored energy is one-half L times current squared, so one-half times 2 times 3 squared equals 9 joules. Therefore the correct answer is B: 9 J.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_014' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_153_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_015' AND NOT (q.topic_id IS 'topic_was_electronics_b002_3' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What principle produces an emf when magnetic flux linkage changes?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The motor effect on a current-carrying conductor","B. Electrostatic induction by a stationary charge","C. Electromagnetic induction","D. Resistive heating in the conductor"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Faraday’s law relates induced emf to the rate of change of flux linkage, with polarity described by Lenz’s law. Therefore the correct answer is C: Electromagnetic induction.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_015' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
